import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"发布与打包指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/advanced/Publishing.md","filePath":"guide/advanced/Publishing.md"}`),a={name:`guide/advanced/Publishing.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="发布与打包指南" tabindex="-1">发布与打包指南 <a class="header-anchor" href="#发布与打包指南" aria-label="Permalink to “发布与打包指南”">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to “前言”">​</a></h2><p>游戏做完了，怎么把它交给玩家？这一篇讲讲<strong>打包、兼容与发布</strong>的注意事项——这些事看起来琐碎，却直接决定玩家能不能顺利打开你的游戏。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已完成<a href="./Case_Study.html">完整实战：打工养成</a>。</p></div><h2 id="一个典型的发布目录" tabindex="-1">一个典型的发布目录 <a class="header-anchor" href="#一个典型的发布目录" aria-label="Permalink to “一个典型的发布目录”">​</a></h2><p>发布时，玩家拿到的应该是一个可以直接运行的文件夹：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>我的游戏/</span></span>
<span class="line"><span> ├─ Emuera1824.exe      ← 引擎本体</span></span>
<span class="line"><span> ├─ CSV/                ← 数据文件</span></span>
<span class="line"><span> ├─ ERB/                ← 脚本</span></span>
<span class="line"><span> ├─ resources/          ← 图片等资源（如果用到）</span></span>
<span class="line"><span> └─ 说明.txt            ← 玩法 / 操作 / 许可说明</span></span></code></pre></div><p><strong>不要</strong>把下面这些一起打包：</p><ul><li><code>emuera.config</code>（玩家自己的设置，不该被覆盖）；</li><li><code>sav/</code>、<code>global.sav</code>、<code>save*.sav</code>（存档）；</li><li><code>emuera.log</code>、<code>debug/</code>（调试产物）。</li></ul><h2 id="需要固定某些配置时" tabindex="-1">需要固定某些配置时 <a class="header-anchor" href="#需要固定某些配置时" aria-label="Permalink to “需要固定某些配置时”">​</a></h2><p>如果你确实需要某些配置对所有玩家生效（例如换行行为、字体），不要直接塞 <code>emuera.config</code>，而是用<strong>强制配置</strong>：</p><ul><li><code>CSV/_default.config</code>：作为默认值，玩家仍可在设置里修改；</li><li><code>CSV/_fixed.config</code>：强制生效，玩家无法修改。</li></ul><p>例如，依赖旧换行行为的脚本可以放一个 <code>_fixed.config</code>：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>ボタンの途中で行を折りかえさない:YES</span></span></code></pre></div><p>详见<a href="./../../translation/Config.html">强制配置项目</a>。</p><h2 id="说明目标引擎" tabindex="-1">说明目标引擎 <a class="header-anchor" href="#说明目标引擎" aria-label="Permalink to “说明目标引擎”">​</a></h2><p>这是<strong>最重要</strong>的一条。不同引擎/改造版支持的特性不同：</p><ul><li>如果只用到 Eramaker / Emuera 共通的功能，兼容性最好；</li><li>如果用了 Emuera 的扩展语法，请在说明里写明“需要 Emuera 及相应版本”；</li><li>如果用了某个改造版的专属功能（图片、动画、工具提示等），务必写清引擎名称与版本。</li></ul><p>可以对照<a href="./../../reference/Compatibility.html">兼容性矩阵</a>与<a href="./../../reference/Version_Index.html">版本特性索引</a>自查。</p><h2 id="脚本编码" tabindex="-1">脚本编码 <a class="header-anchor" href="#脚本编码" aria-label="Permalink to “脚本编码”">​</a></h2><ul><li>脚本通常使用 <strong>Shift-JIS</strong> 编码；如果改成 UTF-8，请确认目标引擎支持；</li><li>存档编码可以在配置里选择（<code>セーブデータをUTF-8で保存する</code>、<code>セーブデータをバイナリ形式で保存する</code>）。<strong>改变存档编码会影响与旧版本的兼容性</strong>，发布前想清楚。</li></ul><h2 id="版本与更新" tabindex="-1">版本与更新 <a class="header-anchor" href="#版本与更新" aria-label="Permalink to “版本与更新”">​</a></h2><p>建议在游戏里维护一个版本号（<code>GameBase.csv</code> 的<code>バージョン</code>），并注意：</p><ul><li>版本号也是存档校验的一部分，改动它可能让旧存档无法读取；</li><li>发布更新时，在说明里写清“是否需要重开”“存档是否兼容”。</li></ul><h2 id="许可与致谢" tabindex="-1">许可与致谢 <a class="header-anchor" href="#许可与致谢" aria-label="Permalink to “许可与致谢”">​</a></h2><ul><li>引擎（Emuera / Eramaker / 改造版）有自己的许可，请遵守并保留其说明文件；</li><li>如果使用了他人提供的素材、脚本、翻译，记得署名致谢；</li><li>本文档项目同样采用开源许可，欢迎在说明里附上链接。</li></ul><h2 id="发布前检查清单" tabindex="-1">发布前检查清单 <a class="header-anchor" href="#发布前检查清单" aria-label="Permalink to “发布前检查清单”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 把 <code>emuera.config</code>、<code>sav/</code>、日志排除在发布包外；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 需要固定的设置改用 <code>_default.config</code> / <code>_fixed.config</code>；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 说明里写清<strong>目标引擎与版本</strong>；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 从零开始能正常进入游戏；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 存档、读档都正常；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 没有会让玩家卡死的死循环；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> 报错信息玩家能看懂；</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> 许可与致谢齐全。</label></li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to “相关链接”">​</a></h2><ul><li><a href="./../../reference/Compatibility.html">兼容性矩阵</a></li><li><a href="./../../reference/Version_Index.html">版本特性索引</a></li><li><a href="./../../translation/Config.html">强制配置项目</a></li><li><a href="./../../translation/Config_Settings.html">配置项详解</a></li><li><a href="./Experience.html">开发实战经验与技巧</a></li></ul>`,30)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};